/**
 * 冒烟：health + status + stats + 匹配 + 租户导出 + 飞轮看板
 */
const base = process.env.SMOKE_BASE || `http://127.0.0.1:${process.env.API_PORT || 3100}`;
const key = process.env.ADMIN_API_KEY || 'yanqi-admin-demo-key';

async function sleepMs(ms) {
  await new Promise((r) => setTimeout(r, ms));
}

async function get(path, auth = false) {
  const headers = {};
  if (auth) headers['X-API-Key'] = key;
  let last = { ok: false, status: 0, body: null };
  for (let attempt = 0; attempt < 4; attempt++) {
    const r = await fetch(base + path, { headers });
    const text = await r.text();
    let body;
    try {
      body = JSON.parse(text);
    } catch {
      body = text;
    }
    last = { ok: r.ok, status: r.status, body };
    const rateLimited =
      r.status === 429 &&
      (String(body?.message || '').includes('请求过于频繁') ||
        String(body?.hintZh || '').includes('公开接口'));
    if (!rateLimited) return last;
    const waitSec = Math.max(1, Number(body?.retryAfterSec) || 2);
    await sleepMs(Math.min(20, waitSec) * 1000);
  }
  return last;
}

async function post(path, body, auth = true) {
  const headers = { 'Content-Type': 'application/json' };
  if (auth) headers['X-API-Key'] = key;
  let last = { ok: false, status: 0, body: null };
  for (let attempt = 0; attempt < 4; attempt++) {
    const r = await fetch(base + path, { method: 'POST', headers, body: JSON.stringify(body || {}) });
    const text = await r.text();
    let parsed;
    try {
      parsed = JSON.parse(text);
    } catch {
      parsed = text;
    }
    last = { ok: r.ok, status: r.status, body: parsed };
    const rateLimited =
      r.status === 429 &&
      (String(parsed?.message || '').includes('请求过于频繁') ||
        String(parsed?.hintZh || '').includes('公开接口'));
    if (!rateLimited) return last;
    const waitSec = Math.max(1, Number(parsed?.retryAfterSec) || 2);
    await sleepMs(Math.min(20, waitSec) * 1000);
  }
  return last;
}

