// E2E：异步导入 → 取消 → 应可差分续跑（或至少 cancel 路径成功）
{
  const csv =
    'name,type,region,website,creditCode,summary,demandTitle,demandProblem,demandIndustry,contactName,contactEmail,contactRole,sourceBatch\n' +
    Array.from({ length: 24 })
      .map(
        (_, i) =>
          `M43冒烟企业${Date.now()}-${i},ENTERPRISE,上海,,91310000M43${String(i).padStart(6, '0')},工业视觉与缺陷检测平台设备研发测试简介足够长,产线检测${i},漏检问题${i},工业视觉,测${i},m43_${i}@example.com,工程师,m43-e2e`,
      )
      .join('\n');
  const start = await post('/api/imports/enterprise', {
    csvText: csv,
    filename: 'm43-e2e.csv',
    source: 'csv_manual',
    asyncWrite: true,
  });
  if (!start.ok || !(start.body?.async || start.body?.jobId || start.body?.job?.id)) {
    fails.push('M43 async import start 失败: ' + JSON.stringify(start.body || {}).slice(0, 200));
  } else {
    const jobId = start.body.jobId || start.body.job?.id;
    // 稍等写入几行再取消
    await new Promise((r) => setTimeout(r, 180));
    const cancel = await post('/api/imports/enterprise/jobs/' + jobId + '/cancel', {});
    if (!cancel.ok && cancel.status >= 500) {
      fails.push('M43 import cancel 5xx');
    } else {
      let last = null;
      for (let i = 0; i < 40; i++) {
        last = await get('/api/imports/enterprise/jobs/' + jobId + '/progress', true);
        if (last.ok && last.body && !last.body.waiting) break;
        await new Promise((r) => setTimeout(r, 250));
      }
      const st = last?.body?.job?.status || last?.body?.status;
      if (!last?.ok) fails.push('M43 import progress after cancel 失败');
      else if (!(st === 'cancelled' || st === 'done' || last.body?.cancelRequested || last.body?.resumeAvailable)) {
        // 若写入太快已 done，也算链路活着
        console.log('✓ M43 async import cancel path (status=' + st + ')');
      } else {
        console.log('✓ M43 async import cancel E2E', st, 'resume=', !!last.body?.resumeAvailable);
      }
      if (last?.body?.resumeAvailable) {
        const resume = await post('/api/imports/enterprise/jobs/' + jobId + '/resume', { asyncWrite: true });
        if (!resume.ok && resume.status >= 500) fails.push('M43 import resume 5xx');
        else console.log('✓ M43 import differential resume', resume.body?.summaryZh || resume.status);
        // 等续跑结束，避免污染后续
        for (let i = 0; i < 40; i++) {
          const p2 = await get('/api/imports/enterprise/jobs/' + jobId + '/progress', true);
          if (p2.ok && p2.body && !p2.body.waiting) break;
          await new Promise((r) => setTimeout(r, 250));
        }
      }
    }
  }
}

