{
  const ac = new AbortController();
  const timer = setTimeout(() => ac.abort(), 2500);
  try {
    const r = await fetch(base + '/api/jobs/progress/stream', {
      headers: { 'X-API-Key': key, Accept: 'text/event-stream' },
      signal: ac.signal,
    });
    const ct = String(r.headers.get('content-type') || '');
    if (!r.ok || !ct.includes('text/event-stream')) {
      fails.push('jobs progress SSE content-type 异常: ' + r.status + ' ' + ct);
    } else console.log('✓ jobs progress SSE', ct.split(';')[0]);
  } catch (e) {
    if (String(e?.name || e).includes('Abort')) console.log('✓ jobs progress SSE (aborted after headers ok)');
    else fails.push('jobs progress SSE 失败: ' + String(e?.message || e).slice(0, 120));
  } finally {
    clearTimeout(timer);
  }
}

