// mint path-bound ticket → correct path OK；wrong path 401；reuse 401
{
  const streamPath = '/api/jobs/progress/stream';
  const mint = await post('/api/jobs/sse-ticket', { purpose: 'smoke-m47', streamPath });
  if (!mint.ok || !mint.body?.ticket || !mint.body?.pathBound) {
    fails.push('M47 sse-ticket path-bound mint 失败: ' + JSON.stringify(mint.body || mint.status).slice(0, 200));
  } else {
    console.log('✓ M47 sse-ticket mint pathBound', mint.body.streamPath);
    // wrong path must 401 and not consume
    const wrong = await fetch(
      base + '/api/imports/enterprise/jobs/x/progress/stream?sse_ticket=' + encodeURIComponent(mint.body.ticket),
      { headers: { Accept: 'text/event-stream' } },
    );
    if (wrong.status !== 401) fails.push('M47 wrong-path sse_ticket 应 401，实际 ' + wrong.status);
    else console.log('✓ M47 wrong-path rejected', wrong.status);

    const ac = new AbortController();
    const timer = setTimeout(() => ac.abort(), 2500);
    try {
      const r = await fetch(base + streamPath + '?sse_ticket=' + encodeURIComponent(mint.body.ticket), {
        headers: { Accept: 'text/event-stream' },
        signal: ac.signal,
      });
      const ct = String(r.headers.get('content-type') || '');
      const via = String(r.headers.get('x-yanqi-sse-auth') || '');
      if (!r.ok || !ct.includes('text/event-stream')) fails.push('M47 correct-path sse_ticket 开流失败: ' + r.status + ' ' + ct);
      else console.log('✓ M47 correct-path stream', via || ct.split(';')[0]);
      const r2 = await fetch(base + streamPath + '?sse_ticket=' + encodeURIComponent(mint.body.ticket), {
        headers: { Accept: 'text/event-stream' },
      });
      if (r2.status !== 401) fails.push('M47 sse_ticket 二次使用应 401，实际 ' + r2.status);
      else console.log('✓ M47 sse_ticket one-time rejected on reuse', r2.status);
    } catch (e) {
      if (String(e?.name || e).includes('Abort')) console.log('✓ M47 sse_ticket stream (aborted after headers)');
      else fails.push('M47 sse_ticket stream 失败: ' + String(e?.message || e).slice(0, 120));
      try {
        const r2 = await fetch(base + streamPath + '?sse_ticket=' + encodeURIComponent(mint.body.ticket), {
          headers: { Accept: 'text/event-stream' },
        });
        if (r2.status !== 401) fails.push('M47 sse_ticket 二次使用应 401，实际 ' + r2.status);
        else console.log('✓ M47 sse_ticket one-time rejected on reuse', r2.status);
      } catch (_) {}
    } finally {
      clearTimeout(timer);
    }
  }
}

