// SSE quota：先重置，再用 limitOverride=3 快速打出 429（不耗尽真实窗口）
{
  const reset = await post('/api/jobs/sse-ticket/quota-reset', { tenantId: 'default' });
  if (!reset.ok) fails.push('M50 quota-reset before burst 失败');
  else console.log('✓ M50 quota-reset before burst', reset.body?.cleared);

  const mint = await post('/api/jobs/sse-ticket', {
    purpose: 'smoke-m50-quota',
    streamPath: '/api/jobs/progress/stream',
    limitOverride: 3,
  });
  if (!mint.ok || !mint.body?.ticket) {
    fails.push('M50 sse-ticket mint/quota 失败: ' + JSON.stringify(mint.body || mint.status).slice(0, 220));
  } else if (!mint.body?.quota || typeof mint.body.quota.remaining !== 'number') {
    fails.push('M50 sse-ticket 应返回 quota.remaining');
  } else {
    console.log('✓ M50 sse-ticket quota remaining', mint.body.quota.remaining, '/', mint.body.quota.limit, mint.body.quota.roleBucket);
    let saw429 = false;
    for (let i = 0; i < 6; i++) {
      const last = await post('/api/jobs/sse-ticket', {
        purpose: 'smoke-m50-quota-burst',
        streamPath: '/api/jobs/progress/stream',
        limitOverride: 3,
      });
      if (last.status === 429) {
        saw429 = true;
        if (last.body?.code !== 'SSE_TICKET_TENANT_QUOTA' || !String(last.body?.messageZh || '').includes('短票')) {
          fails.push('M50 429 应含 SSE_TICKET_TENANT_QUOTA 中文: ' + JSON.stringify(last.body).slice(0, 200));
        } else {
          console.log('✓ M50 sse-ticket 429 Chinese', last.body.retryAfterSec, last.body.roleBucket || '');
        }
        break;
      }
    }
    if (!saw429) fails.push('M50 limitOverride=3 应在数次 mint 后 429');
  }
  // 清窗，避免影响同进程后续人工操作
  await post('/api/jobs/sse-ticket/quota-reset', {});
}

