// —— M56：匹配批写 / 解释缓存 / 核心链路无静默 ——
{
  const health56 = await get('/api/health', false);
  const wave56 = String(health56.body?.maturityWave || '');
  if (
    !health56.ok ||
    !/^M(56|5[7-9]|[6-9][0-9]|1[0-9]{2})/.test(wave56) ||
    Number(health56.body?.maturityApprox) > 0.999 + 1e-9 ||
    !health56.body?.matchSupplyEmbedPrewarmM56 ||
    !health56.body?.matchBatchCreateManyM56 ||
    !health56.body?.importWriteBatchOrgLookupM56 ||
    !health56.body?.explainParallelCacheM56 ||
    !health56.body?.corePathNoSilentE2eM56
  ) {
    fails.push(
      'health M56 flags/wave 失败: ' +
        JSON.stringify({
          wave: health56.body?.maturityWave,
          approx: health56.body?.maturityApprox,
          prewarm: health56.body?.matchSupplyEmbedPrewarmM56,
          batch: health56.body?.matchBatchCreateManyM56,
          importBatch: health56.body?.importWriteBatchOrgLookupM56,
          explain: health56.body?.explainParallelCacheM56,
          e2e: health56.body?.corePathNoSilentE2eM56,
        }).slice(0, 360),
    );
  } else console.log('✓ health M56 flags retained under', health56.body.maturityWave, health56.body.maturityApprox);

  // 核心链路：取一条需求 → 跑匹配（可单 demand）→ 一页纸；全程应有可观察反馈字段
  const demands = await get('/api/demands?take=3', true);
  const demandList = Array.isArray(demands.body)
    ? demands.body
    : demands.body?.items || demands.body?.demands || [];
  const demandId = demandList[0]?.id || null;
  if (!demandId) {
    console.log('· skip M56 demand→match chain (no demand)');
  } else {
    const run = await post('/api/matches/run', { demandId, topN: 3, minScore: 0.15 });
    if (!run.ok || typeof run.body?.count !== 'number') {
      fails.push('M56 matches/run 失败: ' + JSON.stringify(run.body || run.status).slice(0, 260));
    } else {
      console.log('✓ M56 matches/run', run.body.count, 'cancelled=', !!run.body.cancelled);
      const mid =
        run.body.items?.[0]?.matchId ||
        (await get('/api/matches?minScore=0.1', true)).body?.[0]?.id;
      if (!mid) {
        console.log('· skip M56 one-pager after run (no match id)');
      } else {
        const op = await get('/api/matches/' + mid + '/one-pager?fields=sheet&slim=1', true);
        if (!op.ok || !op.body?.ok || !op.body?.onePager) {
          fails.push('M56 one-pager after run 失败: ' + JSON.stringify(op.body || op.status).slice(0, 240));
        } else console.log('✓ M56 demand→match→one-pager', mid.slice(0, 10), op.body.timingMs + 'ms', op.body.cache);

        const ex1 = await get('/api/matches/' + mid + '/explain?fields=core', true);
        if (!ex1.ok || !['M56','M59'].includes(ex1.body?.wave) || ex1.body?.fields !== 'core' || ex1.body?.timingMs == null) {
          fails.push('M56 explain core 失败: ' + JSON.stringify(ex1.body || ex1.status).slice(0, 240));
        } else {
          console.log('✓ M56 explain core', ex1.body.timingMs + 'ms', ex1.body.cache);
          const ex2 = await get('/api/matches/' + mid + '/explain?fields=core', true);
          if (!ex2.ok || ex2.body?.cache !== 'HIT') {
            fails.push('M56 explain cache HIT 失败: ' + JSON.stringify(ex2.body || ex2.status).slice(0, 200));
          } else console.log('✓ M56 explain cache HIT', ex2.body.timingMs + 'ms');
        }
      }
    }
  }

  // 无鉴权应中文 401，不可静默 200
  const noAuth = await get('/api/matches/run'.replace('/api/matches/run', '/api/matches?minScore=0.2'), false);
  // matches list may allow or deny — prefer explain without auth
  const mid2 = (await get('/api/matches?minScore=0.1', true)).body?.[0]?.id;
  if (mid2) {
    const bare = await get('/api/matches/' + mid2 + '/explain?fields=core', false);
    if (bare.status !== 401 && bare.status !== 403 && bare.ok) {
      // some deployments allow public read — soft warn only if unexpected
      console.log('· M56 explain without auth status', bare.status);
    } else if (bare.status === 401 || bare.status === 403) {
      const msg = JSON.stringify(bare.body || '');
      if (!/登录|权限|Unauthorized|401|403|请登录/.test(msg + String(bare.status))) {
        fails.push('M56 explain 401/403 缺中文提示: ' + msg.slice(0, 200));
      } else console.log('✓ M56 explain auth feedback', bare.status);
    }
  }

  const jobs56 = await get('/api/imports/enterprise/jobs?limit=5', true);
  const jobId56 = Array.isArray(jobs56.body)
    ? jobs56.body[0]?.id
    : jobs56.body?.items?.[0]?.id || jobs56.body?.jobs?.[0]?.id || null;
  if (!jobId56) {
    console.log('· skip M56 conflict-preview after import batch flag (no job)');
  } else {
    const prev = await get(
      '/api/imports/enterprise/jobs/' + jobId56 + '/conflict-preview?fields=summary&mergeStrategy=fill-empty',
      true,
    );
    if (!prev.ok || !prev.body?.ok) {
      fails.push('M56 conflict-preview 失败: ' + JSON.stringify(prev.body || prev.status).slice(0, 220));
    } else console.log('✓ M56 import→conflict-preview', prev.body.timingMs + 'ms', prev.body.batchOrgLookup);
  }

  const app56 = await get('/app.js', false);
  const appTxt = String(app56.body || '');
  if (
    !appTxt.includes('m56-skel') ||
    !appTxt.includes('正在打开贡献分') ||
    !appTxt.includes('M56 批写') ||
    !appTxt.includes('登录已失效，无法跑匹配')
  ) {
    fails.push('app.js M56 explain/runMatch 反馈缺失');
  } else console.log('✓ app.js M56 no-silent feedback');

  const ent56 = await get('/work-enterprise.html', false);
  const entTxt = String(ent56.body || '');
  if (
    !entTxt.includes('正在提交需求') ||
    !entTxt.includes('publish-demand') ||
    !entTxt.includes('看一页纸') ||
    !entTxt.includes('登录已失效，请重新登录后再发需求')
  ) {
    fails.push('work-enterprise M56 发需求路径文案缺失');
  } else console.log('✓ work-enterprise demand→inbox→one-pager copy');
}


